package eval

func transactionRecoverySuite() Suite {
	base := concurrentTurnSafetySuite()
	success := map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-b", "amount": 2, "from_gold": 7, "to_gold": 12, "sequence": 1}
	return Suite{ID: "082-transaction-recovery", Name: "Campaign Play 082: Transaction Recovery", Tests: append(base.Tests,
		playTest("play-transaction-source-before-failure", "Public REST confirms source balance before simulated failure", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/currency", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "gold": 9}),
		playTest("play-transaction-target-before-failure", "Public REST confirms target balance before simulated failure", "GET", "/v1/play/campaigns/play-2/characters/play-char-b/currency", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-b", "gold": 10}),
		playTest("play-transaction-non-owner", "Player cannot transactionally transfer from another owned character", "POST", "/v1/play/campaigns/play-2/transactional-transfers", map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-b", "amount": 2, "simulate_failure": false}, map[string]string{"Authorization": playerBAuth}, 403, nil),
		playTest("play-transaction-invalid-member", "Transactional transfer requires campaign characters", "POST", "/v1/play/campaigns/play-2/transactional-transfers", map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-z", "amount": 2, "simulate_failure": false}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-transaction-invalid-amount", "Transactional transfer amount must be positive", "POST", "/v1/play/campaigns/play-2/transactional-transfers", map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-b", "amount": 0, "simulate_failure": false}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-transaction-insufficient-balance", "Transactional transfer rejects insufficient balance without mutation", "POST", "/v1/play/campaigns/play-2/transactional-transfers", map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-b", "amount": 99, "simulate_failure": false}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTestExactJSON("play-transaction-history-empty-before-failure", "Transactional transfer history starts empty", "GET", "/v1/play/campaigns/play-2/transactional-transfers", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"transfers": []any{}}),
		playTestExactJSON("play-transaction-simulated-failure", "Simulated failure returns deterministic 500 after preparation", "POST", "/v1/play/campaigns/play-2/transactional-transfers", map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-b", "amount": 2, "simulate_failure": true}, map[string]string{"Authorization": playerAAuth}, 500, map[string]any{"error": "simulated failure"}),
		playTest("play-transaction-source-after-failure", "Source balance is unchanged after simulated failure", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/currency", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "gold": 9}),
		playTest("play-transaction-target-after-failure", "Target balance is unchanged after simulated failure", "GET", "/v1/play/campaigns/play-2/characters/play-char-b/currency", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-b", "gold": 10}),
		playTestExactJSON("play-transaction-history-empty-after-failure", "Simulated failure did not append transfer history", "GET", "/v1/play/campaigns/play-2/transactional-transfers", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"transfers": []any{}}),
		playTestExactJSON("play-transaction-success", "Successful transactional transfer commits debit credit and record once", "POST", "/v1/play/campaigns/play-2/transactional-transfers", map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-b", "amount": 2, "simulate_failure": false}, map[string]string{"Authorization": playerAAuth}, 201, success),
		playTest("play-transaction-source-after-success", "Source balance reflects one committed transfer", "GET", "/v1/play/campaigns/play-2/characters/play-char-w/currency", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "gold": 7}),
		playTest("play-transaction-target-after-success", "Target balance reflects one committed transfer", "GET", "/v1/play/campaigns/play-2/characters/play-char-b/currency", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-b", "gold": 12}),
		playTestExactJSON("play-transaction-history-after-success", "Members read exact ordered successful transaction history", "GET", "/v1/play/campaigns/play-2/transactional-transfers", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"transfers": []any{success}}),
		playTest("play-transaction-history-nonmember-forbidden", "Non-member cannot read transactional transfer history", "GET", "/v1/play/campaigns/play-2/transactional-transfers", nil, map[string]string{"Authorization": "Bearer session-stranger"}, 403, nil),
	)}
}
